import { L, info, mc, tf, fill, fillc, type, order, match } from '../_h.js';

export default {
  sensors: [
    L('The eyes and ears of a car',
      info('Why cars need sensors', 'A driver-assistance system must know what is around the vehicle: other cars, pedestrians, lanes, kerbs.\n\nIt uses four main sensor types, each built on different physics: **camera** (light), **radar** (radio waves), **lidar** (laser light) and **ultrasonic** (sound).'),
      match('Match the sensor to what it sends or receives', [['Camera', 'Visible light from the scene'], ['Radar', 'Radio waves'], ['Lidar', 'Laser pulses'], ['Ultrasonic', 'High-frequency sound']]),
      match('Match the sensor to its typical output', [['Camera', 'A colour image'], ['Radar', 'Detections with range, speed and angle'], ['Lidar', 'A 3-D point cloud'], ['Ultrasonic', 'A short distance']]),
      mc('Which sensor is used for parking at very short range because it is cheap?', ['Ultrasonic', 'Lidar', 'Long-range radar', 'Front camera'], 'A few metres of range, centimetre accuracy.'),
      mc('Which sensor can read a speed-limit sign?', ['Camera', 'Radar', 'Ultrasonic', 'None'], 'Only the camera sees colour and fine texture.'),
      mc('Which sensor measures the speed of another car directly?', ['Radar', 'Camera', 'Ultrasonic', 'A standard lidar'], 'Through the Doppler effect.'),
      tf('One sensor type is enough for safe automated driving in all conditions.', false, 'Each has blind spots; they are combined.'),
      mc('Active sensors (radar, lidar, ultrasonic) differ from a camera because they…', ['Emit their own signal and measure the echo', 'Need daylight', 'Produce colour images', 'Have no range limit'], 'So they work in darkness.')),

    L('Measuring distance and speed',
      info('Time of flight', 'Send a pulse, wait for the echo. The signal travels to the object **and back**, so:\n\n```\ndistance = speed × time / 2\n```\n\nSound travels about 343 m/s in air. Light and radio waves travel about 300,000,000 m/s.'),
      type('An ultrasonic echo returns after 0.01 s. Sound travels 340 m/s. How far is the object, in metres?', ['1.7'], '340 × 0.01 / 2.'),
      mc('Why divide by two?', ['The pulse travels there and back', 'There are two sensors', 'Sound is half as fast', 'To convert to feet'], 'The measured time covers both directions.'),
      mc('Cold air slows the speed of sound. If the software ignores temperature, distances are…', ['Slightly wrong', 'Unaffected', 'Doubled', 'Zero'], 'Speed is about 331 + 0.6 × temperature in °C.'),
      info('Doppler', 'When an object moves toward a radar, the reflected wave comes back at a slightly **higher frequency**; moving away, lower. This shift gives the **radial velocity** directly, in one measurement:\n\n```\nv = f_doppler × c / (2 × f_carrier)\n```'),
      mc('A car drives straight toward the radar. The reflected frequency is…', ['Higher than transmitted', 'Lower than transmitted', 'Unchanged', 'Zero'], 'Like the rising pitch of an approaching siren.'),
      mc('A car crosses exactly sideways in front of the radar. Its radial velocity is about…', ['Zero', 'Its full speed', 'Twice its speed', 'Negative infinity'], 'Radar measures only the component along the line of sight.'),
      type('Radar range resolution is c / (2 × bandwidth). With 1 GHz of bandwidth and c = 300,000,000 m/s, what is it in centimetres?', ['15'], '3e8 / 2e9 = 0.15 m.')),

    L('Strengths, weaknesses and weather',
      info('No free lunch', '| Sensor | Good at | Weak at |\n| --- | --- | --- |\n| Camera | Classification, lanes, signs | Depth, night, glare, fog |\n| Radar | Speed, range, bad weather | Angular detail, stationary clutter |\n| Lidar | Precise 3-D shape | Cost, heavy rain and fog |\n| Ultrasonic | Close range, cheap | Anything beyond a few metres |'),
      mc('In thick fog, which sensor keeps working best?', ['Radar', 'Camera', 'Lidar', 'None of them'], 'Radio waves pass through fog; light is scattered.'),
      mc('At night with no street lights, which sensor suffers most?', ['Camera', 'Radar', 'Lidar', 'Ultrasonic'], 'It depends on external light.'),
      mc('Which sensor gives the most precise 3-D shape of an object?', ['Lidar', 'Radar', 'Ultrasonic', 'A single camera'], 'A dense point cloud with centimetre accuracy.'),
      mc('Radar struggles to separate two objects that are side by side at the same range and speed because of its…', ['Low angular resolution', 'Low range', 'Colour blindness', 'High price'], 'Its beam is wide compared with a camera pixel.'),
      mc('Why are stationary objects hard for radar?', ['They blend with reflections from the road, bridges and guard rails', 'They do not reflect', 'Radar only sees metal', 'They move too fast'], 'Clutter has the same zero relative ground speed.'),
      match('Match the situation to the sensor that helps most', [['Reading a traffic light', 'Camera'], ['Measuring closing speed in rain', 'Radar'], ['Mapping the exact shape of a kerb', 'Lidar'], ['Parking 30 cm from a wall', 'Ultrasonic']]),
      tf('Because their failure modes differ, combining sensors gives redundancy.', true, 'They rarely fail in the same way at the same time.')),

    L('Signal chain and interview level',
      info('From waves to objects (radar)', 'An **FMCW** radar transmits **chirps** whose frequency rises steadily.\n\n1. Mix the echo with the transmitted chirp: the **beat frequency** gives **range**.\n2. Phase change across chirps gives **Doppler** (speed).\n3. Phase differences across antennas give **angle**.\n4. **CFAR** picks detections above the noise.\n5. Cluster and **track**.'),
      order('Order the radar processing chain', ['Transmit chirps and receive echoes', 'FFT across samples: range', 'FFT across chirps: Doppler', 'Angle estimation across antennas', 'CFAR detection', 'Clustering and tracking'], 'Raw signal to object list.'),
      mc('What does CFAR do?', ['Sets a detection threshold that adapts to the local noise level', 'Measures colour', 'Compresses data', 'Calibrates the camera'], 'Constant false-alarm rate.'),
      mc('Every sensor reports in its own coordinate frame. To combine them you need…', ['Each sensor’s mounting position and orientation (extrinsics)', 'More sensors', 'A faster CPU', 'Nothing'], 'Transform everything into the vehicle frame.'),
      type('A front radar is mounted 3.5 m ahead of the vehicle origin, facing forward. It sees an object 10 m straight ahead. What is the object’s x in the vehicle frame, in metres?', ['13.5'], '3.5 + 10.'),
      info('Sensor health', 'Sensors get dirty, knocked out of alignment and disturbed by other radars.\n\n**Blockage detection** is often a classifier on statistics over a time window: number of detections, signal strength, maximum range. The hard part is telling a blocked sensor from an empty road.'),
      mc('Which feature would help detect a mud-covered radar?', ['A sustained drop in detection count and signal strength', 'The colour of the mud', 'The outside temperature only', 'The radio volume'], 'Compare with what is expected at the current speed and scene.'),
      mc('Why might a blockage classifier raise false alarms in the desert?', ['An empty scene also has few detections', 'Sand is invisible', 'It is too hot for radar', 'There is no GPS'], 'Add context features such as road-surface returns.'),
      order('Order a strong answer to "Compare the sensors"', ['State what each measures and its physics', 'Give each one’s main strength', 'Give each one’s main weakness', 'Conclude that they are complementary and fused for redundancy'], 'Structure makes it memorable.')),

    L('Beyond the basics: lidar, bandwidth and angle',
      info('Lidar is time of flight with light', 'A lidar fires a very short laser pulse and times the echo. The idea is the same as ultrasonic, but the speed is the speed of light:\n\n```\nrange = c × t / 2      (c = 300,000,000 m/s)\n```\n\nThe time is tiny: an object 30 m away returns the pulse in only 200 nanoseconds, so the electronics must be very fast.'),
      type('A lidar pulse returns after 200 ns. Using c = 300,000,000 m/s, how far is the object, in metres?', ['30'], '3e8 × 200e-9 / 2 = 30 m.'),
      tf('A radar chirp with 4 GHz of bandwidth can separate objects that are closer together in range than a chirp with 1 GHz.', true, 'Range resolution is c / (2 × bandwidth), so more bandwidth means finer resolution.'),
      type('What is the range resolution of a radar with 4 GHz of bandwidth, in centimetres? Use c = 300,000,000 m/s.', ['3.75'], '3e8 / 8e9 = 0.0375 m.'),
      info('Angle is the weak axis', 'Sideways separation at range r for an angle θ (in radians) is roughly:\n\n```\ncross-range gap ≈ r × θ\n```\n\nA radar beam of 5° (0.087 rad) at 50 m spans about 4.4 m, wider than a 3.5 m lane. A camera pixel covers a tiny angle, so it separates objects sideways far better.'),
      mc('Two cars drive side by side in adjacent lanes 50 m ahead, about 3.5 m apart. A radar with a 5° angular resolution…', ['May report them as one object', 'Always separates them', 'Cannot see either', 'Measures their colour instead'], 'The beam is about 4.4 m wide at that range.'),
      mc('A camera has 1920 pixels across a 60° field of view. About how wide is one pixel at 100 m?', ['About 5.5 cm', 'About 55 cm', 'About 5.5 m', 'About 0.5 cm'], '60° / 1920 = 0.031°, which is 0.00055 rad; times 100 m.'),
      type('A 77 GHz radar sees a car closing at 30 m/s. Using f_doppler = 2 × v × f_carrier / c with c = 300,000,000 m/s, what is the Doppler shift in kHz?', ['15.4'], '2 × 30 × 77e9 / 3e8 = 15,400 Hz.'),
      match('Match the quantity to what mainly limits it', [['Range resolution', 'Chirp bandwidth'], ['Angular resolution', 'Antenna aperture and number of antennas'], ['Velocity resolution', 'Duration of the chirp frame'], ['Maximum range', 'Transmit power and receiver sensitivity']])),

    L('Common mistakes and debugging',
      info('Sensor bugs are usually boring', 'Most fusion bugs are not clever. They come from four places, so check them in this order:\n\n1. **Units:** degrees against radians, milliseconds against seconds.\n2. **Frames:** sensor frame against vehicle frame, and sign conventions.\n3. **Time:** stamping data on arrival instead of at measurement.\n4. **Physics:** multipath, clutter, weather.\n\nOnly then suspect the algorithm.'),
      mc('A radar object list gives range and azimuth in degrees. What is wrong with this code?', ['Degrees are passed to a function that expects radians', 'The range should be squared', 'The azimuth should be added to the range', 'Nothing'], 'math.cos and math.sin work in radians, so convert with math.radians first.', 'x = r * math.cos(az_deg)\ny = r * math.sin(az_deg)'),
      mc('An ultrasonic parking sensor reports every obstacle at exactly twice its true distance. A likely cause is…', ['The code forgot to divide the time of flight by two', 'The speed of sound was set to zero', 'The sensor is too cold', 'The echo was too weak'], 'The pulse travels there and back.', 'distance = 343 * echo_time     # metres'),
      type('A sensor’s data are stamped when they reach the computer, 80 ms after they were measured. The car drives at 20 m/s. How many metres is the position error?', ['1.6'], '20 × 0.08 = 1.6 m.'),
      tf('Stamping a measurement with the time it arrives at the computer is fine, because transport delay is always negligible.', false, 'Delays of tens of milliseconds are common and cause metres of error at speed.'),
      mc('A radar reports a phantom car beyond a metal guard rail, at about twice the true distance of a real car. The best explanation is…', ['Multipath: the signal bounced off the rail before reflecting back', 'The camera is dirty', 'Doppler aliasing of a parked car', 'Low battery'], 'Longer reflection paths look like longer ranges.'),
      mc('A lidar in heavy rain reports many points floating in empty air a few metres ahead. A sensible first step is…', ['Filter low-intensity, isolated points and use multiple returns per pulse', 'Raise the laser power', 'Ignore the lidar for ever', 'Convert the points to degrees'], 'Raindrops give weak, isolated returns.'),
      info('A debugging order that saves days', 'When a fused object sits in the wrong place, do not tune the filter first. Plot raw detections from one sensor in the vehicle frame against a known target such as a corner reflector. If they are offset, the fault is upstream: calibration, units or time.'),
      match('Match the symptom to its likely cause', [['Offset that grows with distance', 'Angular misalignment (yaw error)'], ['Constant offset at every range', 'Wrong mounting position in the extrinsics'], ['Object trails behind a fast car', 'Late or wrong timestamps'], ['Every distance doubled', 'Missing division by two']]),
      order('Order the steps to debug a fused object that is 1.5 m too far ahead', ['Record the raw detections from one sensor and a reference target', 'Check units and the sensor mounting offsets', 'Check timestamps against the measurement time', 'Check calibration for angular error', 'Only then tune the filter or association'], 'Rule out simple causes first.')),

    L('Case study: automatic emergency braking',
      info('The scenario', 'A car drives at 20 m/s (72 km/h) on a road. Traffic ahead has stopped. The **automatic emergency braking** (AEB) function must warn the driver and, if there is no reaction, brake hard. It uses a front radar and a front camera.\n\nYou will make the design decisions step by step.'),
      mc('At 120 m, which sensor first gives you a reliable closing speed on the stopped queue?', ['Radar, through the Doppler shift', 'Camera, from object size alone', 'Ultrasonic', 'Rear radar'], 'Radar measures range and radial speed directly in one measurement.'),
      type('The car is 60 m from the stopped queue and moves at 20 m/s. What is the time to collision, in seconds?', ['3'], '60 / 20.'),
      type('The car can brake at 8 m/s². How far does it need to stop from 20 m/s, in metres? (v² / (2a))', ['25'], '400 / 16 = 25 m.'),
      mc('The queue is now 30 m ahead. Braking needs 25 m, and the system has 0.2 s of latency, which is 4 m at 20 m/s. What should AEB do?', ['Brake at full force now: the margin is only 1 m', 'Wait another second for more certainty', 'Only sound a warning', 'Do nothing, because 25 m is less than 30 m'], '25 m plus 4 m of latency leaves almost no margin.'),
      info('The hard part is not braking, it is not braking by mistake', 'A false emergency stop on a motorway can cause a rear-end crash. Radar sees many strong stationary returns: bridges, signs, manhole covers. So the system never brakes on one sensor, one frame or an unclassified object.'),
      mc('Radar reports a strong stationary return 70 m ahead under a bridge. Before braking hard you should require…', ['A confirmed track plus camera evidence of a vehicle or obstacle in your lane', 'Nothing: strong echoes are always real', 'A louder warning', 'A faster radar'], 'Fusion removes overhead and roadside clutter.'),
      order('Order the AEB decision chain', ['Radar detects an object and measures range and closing speed', 'The tracker confirms the object over several cycles', 'The camera classifies it and checks it is in the ego lane', 'Time to collision is computed against the braking distance', 'Warn first, then brake partially, then brake fully'], 'Detect, confirm, classify, assess, act in stages.'),
      mc('In heavy rain at night the camera cannot see the lane markings well. A responsible design…', ['Lowers the camera’s trust, limits the function to warnings or lower speeds, and tells the driver', 'Continues exactly as before', 'Disables the radar', 'Brakes more often to be safe'], 'Degradation must be detected and handled, not hidden.'),
      tf('For AEB, a very low rate of false braking is as important as a high detection rate.', true, 'Unneeded emergency braking is itself a hazard and drivers switch off a system that cries wolf.')),

    L('Interview drill: sensors',
      info('How the questions really go', 'Interviewers rarely ask "list the sensors". They ask a **scenario** and then push with follow-ups: "why not use lidar?", "what happens in fog?", "how would you check that?".\n\nA strong answer states the physics, gives the trade-off and ends with a way to verify it.'),
      mc('"Why not use only lidar for a mass-market driver-assistance car?" The best first point is…', ['Cost, size and weaker performance in heavy rain and fog, plus no direct speed measurement in standard lidar', 'Lidar is illegal', 'Lidar cannot measure distance', 'Lidar works only at night'], 'Name the trade-off, not a slogan.'),
      type('Quick-fire: an echo returns after 0.02 s. Sound travels at 343 m/s. How far is the object, in metres?', ['3.43'], '343 × 0.02 / 2 = 3.43.'),
      mc('Follow-up: "The temperature is -10 °C and you still use 343 m/s. Is the measured distance too long or too short?"', ['Too long, because sound is really slower, about 325 m/s', 'Too short, because sound is faster', 'Exactly right', 'It becomes negative'], 'Speed is about 331 + 0.6 × T; the software overestimates the speed.'),
      match('Match the interviewer’s question to the idea your answer must contain', [['Why does radar work in fog?', 'Radio waves are barely scattered by water droplets'], ['Why can’t radar tell a child from a pole?', 'Low angular and shape resolution'], ['Why does a camera struggle with depth?', 'A single image has no direct range'], ['Why are sensors mounted behind the bumper or windscreen?', 'Protection, with a cover that lets the signal through']]),
      mc('The interviewer says: "Your radar misses a stationary stalled car. Why?" The strongest answer is…', ['Many systems suppress stationary returns because of clutter, so fusion with the camera is needed to confirm them', 'Radar cannot see metal', 'The stalled car has no speed so it has no range', 'The camera is always wrong'], 'Stationary targets look like road furniture.'),
      info('A shape for every answer', 'Use four beats: **what it measures**, **why it works (physics)**, **where it fails**, **how you would combine or verify it**. If you do not know, say so, then reason aloud from the physics. That is better than bluffing.'),
      order('Order a strong answer to "How would you choose sensors for a low-cost lane-keeping and cruise-control car?"', ['State the functions and the conditions they must work in', 'Choose a front camera for lanes and classes and a front radar for range and speed', 'Explain how each covers the other’s weakness in fog, night and glare', 'Mention cost, packaging and the need for calibration', 'Say how you would validate it on recorded drives in all weather'], 'Requirements, choice, justification, constraints, verification.'),
      tf('If you do not know the answer to a follow-up, it is better to say so and reason from first principles than to guess confidently.', true, 'Interviewers check how you think and how honest you are.'))
  ],

  kalman: [
    L('Estimating what you cannot see exactly',
      info('Every measurement is noisy', 'A radar says the car ahead is 50.3 m away, then 49.8, then 50.6. The car did not jump: the **measurements are noisy**.\n\nWe want the best **estimate** of the true state, and an idea of how **uncertain** we are.'),
      mc('Three noisy measurements of the same fixed distance: 9, 10, 11. A sensible estimate?', ['10', '9', '11', '30'], 'Averaging reduces random noise.'),
      info('Trust the better sensor more', 'Sensor A is precise, sensor B is sloppy. A plain average wastes A’s quality. Weight each by **1 / variance**:\n\n```\nvariance = 1 / (1/var1 + 1/var2)\nmean = variance × (m1/var1 + m2/var2)\n```\n\nThe fused variance is always **smaller** than either input.'),
      type('Two sensors report 10 and 12 with equal variance. What is the fused estimate?', ['11'], 'Equal trust: the plain average.'),
      type('Two measurements each have variance 1. What is the variance of the fused estimate?', ['0.5', '.5', '1/2'], '1 / (1 + 1).'),
      mc('Sensor A: 10 with variance 1. Sensor B: 20 with variance 9. The fused estimate is…', ['Close to 10', 'Close to 20', 'Exactly 15', 'Above 20'], 'A is nine times more trusted. The result is 11.'),
      tf('Fusing two independent measurements gives an estimate more certain than either one.', true, 'More information, less uncertainty.'),
      match('Match the term', [['State', 'What we want to know, such as position and speed'], ['Measurement', 'What the sensor reports'], ['Variance', 'How uncertain a value is'], ['Estimate', 'Our best guess of the state']])),

    L('Predict and update',
      info('The Kalman loop', 'The filter repeats two steps for ever:\n\n**Predict:** use a motion model to move the state forward in time. Uncertainty **grows**.\n\n**Update:** compare with a new measurement and correct. Uncertainty **shrinks**.'),
      order('Order one cycle of a Kalman filter', ['Predict the state forward in time', 'Increase the uncertainty by the process noise', 'Compute the gain from the two uncertainties', 'Correct the state toward the measurement', 'Reduce the uncertainty'], 'Predict, then update.'),
      info('The gain', 'The **Kalman gain** K says how far to move toward the measurement:\n\n```\nK = P / (P + R)\nx = x + K × (z - x)\n```\n\n`P` is how unsure the prediction is. `R` is how noisy the sensor is. K is between 0 and 1.'),
      type('P = 1 and R = 1. What is the gain K?', ['0.5', '.5', '1/2'], '1 / (1 + 1).'),
      type('Estimate x = 0, measurement z = 10, gain K = 0.5. What is the new estimate?', ['5'], '0 + 0.5 × (10 - 0).'),
      mc('The sensor is extremely noisy (R is huge). The gain is…', ['Close to 0: mostly ignore the measurement', 'Close to 1', 'Exactly 0.5', 'Negative'], 'Trust the prediction.'),
      mc('The prediction is very uncertain (P is huge). The gain is…', ['Close to 1: follow the measurement', 'Close to 0', 'Exactly 0.5', 'Greater than 2'], 'Trust the sensor.'),
      fillc('P = P + Q\nK = P / (P + ___)\nx = x + K * (z - x)\nP = (1 - K) * P', ['R', 'Q', 'x', 'z'], 'Prediction uncertainty against measurement noise.')),

    L('Tracking a moving object',
      info('Position and velocity', 'To track a car we keep a **state vector** `[position, velocity]` and a **covariance matrix** P.\n\nThe constant-velocity model predicts:\n\n```\nposition = position + velocity × dt\nvelocity = velocity\n```\n\nAs a matrix: `F = [[1, dt], [0, 1]]`.'),
      type('Position 10 m, velocity 2 m/s, dt = 0.5 s. Predicted position in metres?', ['11'], '10 + 2 × 0.5.'),
      mc('The sensor measures only position. Can the filter estimate velocity?', ['Yes, from how position changes over time', 'No, never', 'Only with a second sensor', 'Only if velocity is zero'], 'Position and velocity are linked through the model, via the covariance.'),
      match('Match the matrix', [['F', 'Motion model: how the state evolves'], ['H', 'Measurement model: what the sensor sees'], ['Q', 'Process noise: how wrong the model can be'], ['R', 'Measurement noise: how noisy the sensor is']]),
      mc('You increase Q. The filter becomes…', ['More responsive and noisier', 'Smoother and slower', 'Unstable for certain', 'Unchanged'], 'It trusts its model less, so it follows measurements more.'),
      mc('The tracked car brakes hard and your estimate lags behind. Likely cause?', ['Q is too small for that manoeuvre', 'R is too small', 'dt is negative', 'The sensor is too accurate'], 'The filter trusts a constant-velocity model too much.'),
      mc('The **innovation** is…', ['The measurement minus the predicted measurement', 'The Kalman gain', 'The process noise', 'The time step'], 'It drives the correction and is used for gating.'),
      tf('Fusing radar and camera in one filter means running an update for each measurement with its own R.', true, 'Each sensor contributes according to its noise.')),

    L('Non-linear filters and interview level',
      info('When the world is not linear', 'The basic filter assumes linear models. But a radar measures **range and angle**, which are non-linear functions of x and y, and turning vehicles do not move in straight lines.\n\n- **EKF:** linearise with a Jacobian around the current estimate.\n- **UKF:** push a few "sigma points" through the true function.'),
      match('Match the filter to the situation', [['Linear Kalman filter', 'Linear motion and measurement'], ['Extended Kalman filter', 'Mild non-linearity, uses Jacobians'], ['Unscented Kalman filter', 'Stronger non-linearity, uses sigma points'], ['Particle filter', 'Multi-modal or very non-Gaussian problems']]),
      mc('Why does a radar measurement need an EKF or UKF with a Cartesian state?', ['Range and azimuth are non-linear functions of x and y', 'Radar is too fast', 'Radar has no noise', 'The state is too small'], 'range = sqrt(x² + y²), azimuth = atan2(y, x).'),
      mc('A track receives no detection for three cycles (occlusion). A good tracker…', ['Keeps predicting with growing uncertainty, then deletes it if still unmatched', 'Deletes it immediately', 'Freezes it in place', 'Resets all tracks'], 'Called coasting.'),
      mc('What is gating?', ['Ignoring detections too far from the predicted position, given the uncertainty', 'Opening a file', 'Scaling the image', 'Lowering the frame rate'], 'It prevents wrong associations.'),
      mc('How would you obtain R for a sensor?', ['From its specification or by measuring its error against a reference', 'Guess a large number', 'Set it to zero', 'Copy Q'], 'Then tune Q to match real manoeuvres.'),
      order('Order a strong answer to "Explain the Kalman filter"', ['It estimates a hidden state from noisy measurements', 'Predict: move the state forward with a model; uncertainty grows', 'Update: correct with the measurement; uncertainty shrinks', 'The gain weights model against sensor by their uncertainties', 'It is optimal for linear models with Gaussian noise'], 'Plain words first, equations if asked.'),
      mc('A filter is "inconsistent" when…', ['Its real errors are larger than its own covariance claims', 'It runs too fast', 'It uses floats', 'It has two states'], 'Check that innovations match their predicted covariance.'),
      tf('A Kalman filter is cheap enough to run on an embedded ECU.', true, 'A few small matrix operations per cycle.')),

    L('Covariance and one full cycle with numbers',
      info('Covariance, not just variance', 'For a state `[position, velocity]` the filter keeps a 2 × 2 matrix **P**.\n\nThe diagonal holds the **variance** of each state. The off-diagonal holds the **correlation** between their errors. That link is what lets a position-only sensor correct the velocity estimate.'),
      mc('What does the off-diagonal entry of P describe?', ['How the errors of position and velocity are correlated', 'The time step', 'The sensor noise', 'The number of measurements'], 'A position error often goes together with a velocity error.'),
      info('One cycle in numbers', 'Take a 1-D example. Prediction uncertainty P = 4, sensor noise R = 1.\n\n```\nK = P / (P + R) = 4 / 5 = 0.8\nx = x + K × (z - x)\nP = (1 - K) × P\n```\n\nThe estimate moves 80 % of the way to the measurement and P shrinks.'),
      type('P = 4 and R = 1. What is the gain K?', ['0.8', '.8', '4/5'], '4 / (4 + 1).'),
      type('The estimate is x = 10, the measurement is z = 12 and K = 0.8. What is the new estimate?', ['11.6'], '10 + 0.8 × 2.'),
      type('After the update, what is the new P = (1 - K) × P, with P = 4 and K = 0.8?', ['0.8', '.8'], '0.2 × 4.'),
      type('Next cycle the filter predicts and adds process noise Q = 0.2 to P = 0.8, giving 1.0. With R = 1, what is the new gain?', ['0.5', '.5', '1/2'], '1 / (1 + 1).'),
      mc('If Q and R stay constant, what happens to P and K after many cycles?', ['They settle to steady values', 'P grows without limit', 'K becomes negative', 'They oscillate forever'], 'Predict adds uncertainty and update removes it; the two balance.'),
      mc('The innovation is 3 m with an innovation variance S = 4 m². The normalised value is 3² / 4 = 2.25. A common 95 % limit for one degree of freedom is 3.84. The measurement is…', ['Consistent: accept it', 'Inconsistent: reject it', 'Impossible', 'Proof that Q is zero'], '2.25 is below 3.84.'),
      tf('The predict step makes the estimate more certain.', false, 'Uncertainty grows when you predict; only the update shrinks it.')),

    L('Common mistakes and debugging',
      info('Silent failures', 'A Kalman filter rarely crashes. It just gives plausible but wrong output. Typical causes: **forgetting Q**, **wrong units for dt**, **wrong sign of the innovation**, **angles that wrap around**, and **noise values that do not match reality**.'),
      mc('This filter becomes more and more confident and eventually ignores every measurement. What is missing?', ['Process noise Q is not added to P in the predict step', 'The gain is too small', 'The state is too large', 'The measurement is too good'], 'Without Q, P shrinks towards zero and so does K.', 'def predict(x, P, F):\n    x = F @ x\n    P = F @ P @ F.T      # no + Q\n    return x, P'),
      mc('The tracked car moves at 20 m/s and your code uses dt = 50 because timestamps are in milliseconds. After one prediction the position…', ['Jumps by about 1000 m', 'Moves 1 m', 'Does not change', 'Moves backwards'], '20 × 50 = 1000; use 0.05 s.', 'x_pos = x_pos + v * dt    # dt = 50'),
      mc('This update makes the estimate run away from the measurement. Why?', ['The innovation has the wrong sign', 'K is too small', 'R is too large', 'dt is zero'], 'The correction must be z minus the prediction.', 'y = x_pred - z\nx = x_pred + K * y'),
      type('A bearing is measured as 179° and the prediction is -179°. After wrapping the innovation into the range -180° to 180°, what is it, in degrees?', ['-2'], '179 - (-179) = 358, which wraps to -2.'),
      tf('If the plot of the estimate looks smooth, the filter must be working correctly.', false, 'A smooth estimate can be badly lagging or biased; check the innovations.'),
      info('How to debug a filter', 'Log the **innovations**. For a healthy filter they have mean near zero, are not correlated from step to step, and about 95 % lie within ±2 standard deviations (√S). A bias means a wrong model or sensor offset. Too large means Q or R is too small.'),
      mc('The innovations are consistently positive over a long straight stretch. A likely cause is…', ['A bias in the sensor or the model', 'Perfect tuning', 'Too many states', 'A fast CPU'], 'Healthy innovations average zero.'),
      match('Match the symptom to the likely cause', [['The estimate lags behind a braking car', 'Q is too small'], ['The estimate jitters like the raw sensor', 'R is too small or Q too large'], ['The covariance shrinks to zero and data are ignored', 'Q is missing in predict'], ['Position jumps by huge amounts', 'Time step in the wrong units']]),
      order('Order the steps to debug a filter that drifts away from the truth', ['Log innovations and the covariance', 'Check units and the sign of the innovation', 'Check that angles are wrapped', 'Compare innovation spread with the predicted S', 'Adjust Q and R last'], 'Fix bugs before tuning.')),

    L('Case study: a cruise-control radar track',
      info('The scenario', 'An adaptive cruise control must follow the car ahead. The radar delivers range at **10 Hz**, so dt = 0.1 s. The state is `[range, closing speed]`. Range is 50.0 m and the car ahead is closing at 2 m/s, so the closing speed is -2 m/s.\n\nYou make the design choices.'),
      mc('Radar measures range and Doppler speed directly. What should the measurement model H do?', ['Observe both range and relative speed', 'Observe only the angle', 'Observe only the time', 'Observe nothing'], 'Both states are measured, with their own noise.'),
      type('Predict the range after one step: 50.0 + (-2) × 0.1. What is it, in metres?', ['49.8'], '50.0 - 0.2.'),
      type('The radar then measures 49.5 m. With P = 1 and R = 0.25 the gain is 0.8. What is the updated range, in metres?', ['49.56'], '49.8 + 0.8 × (49.5 - 49.8).'),
      mc('R is chosen as 0.25 m² (sigma 0.5 m). Where should that value come from?', ['The data sheet and measured error against a reference on test drives', 'A guess of 100', 'Copying Q', 'Zero'], 'It should reflect real sensor error.'),
      info('What the real road does', 'Cars cut in, drive behind trucks and brake hard. A good tracker copes with: **cut-ins** (a new object appears closer), **occlusion** (no detection for a few frames) and **sudden braking** (the model is wrong).'),
      mc('A car cuts in at 20 m while the tracked car is at 50 m. The innovation for the existing track is huge. The tracker should…', ['Gate it out, start a new track for the cut-in and choose the closest in-lane object as the target', 'Update the old track with it', 'Average the two ranges', 'Delete both tracks'], 'The detection is far outside the old track’s uncertainty.'),
      type('The track has range 49.56 m and speed -2 m/s. The radar misses three frames (0.3 s). What is the coasted range, in metres?', ['48.96'], '49.56 - 2 × 0.3.'),
      order('Order the life of the cruise-control target track', ['A new detection starts a tentative track', 'Several consistent hits confirm it', 'Each cycle predicts, gates and updates it', 'Missed frames make it coast with growing uncertainty', 'Too many misses delete it'], 'Tentative, confirmed, updated, coasting, deleted.'),
      mc('The car ahead brakes at 6 m/s² but your constant-velocity filter reacts late. The simplest fix is to…', ['Increase Q for speed, or use a model that includes acceleration', 'Decrease R', 'Lower the frame rate', 'Remove the gate'], 'The model must admit it can be wrong.')),

    L('Interview drill: Kalman filters',
      info('What interviewers look for', 'They want to hear the **idea in plain words**, a **number** you can compute at the whiteboard, and **what goes wrong** when Q and R are wrong. Typical follow-ups: "why not a moving average?", "what if Q is zero?", "how do you handle different sensor rates?"'),
      mc('"Why a Kalman filter instead of a moving average?" The best answer is…', ['It uses a motion model and weights by uncertainty, and it also gives you the uncertainty', 'It is faster to type', 'It needs no tuning', 'It works only for position'], 'A moving average ignores dynamics and sensor quality.'),
      mc('Follow-up: "What happens if you set Q to zero?"', ['The filter becomes overconfident and ends up ignoring new measurements', 'It becomes more responsive', 'It stops compiling', 'Nothing'], 'P shrinks towards zero, so K does too.'),
      mc('Follow-up: "And if R is zero, with P above zero?"', ['The gain is 1 and the estimate simply equals the measurement', 'The gain is 0', 'The filter diverges to infinity', 'P grows'], 'K = P / (P + 0) = 1.'),
      type('Quick-fire: P = 3 and R = 1. What is the gain K?', ['0.75', '.75', '3/4'], '3 / 4.'),
      match('Match the interviewer’s question to the key idea', [['Why does P grow in predict?', 'The model is imperfect, so Q is added'], ['Why is the filter cheap?', 'A few small matrix operations per cycle'], ['What does gating do?', 'Rejects detections too far from the prediction'], ['What is the innovation?', 'Measurement minus predicted measurement']]),
      mc('"A 30 Hz camera and a 20 Hz radar feed one filter. How do you handle it?" A good answer is…', ['Predict to each measurement’s timestamp and update in time order with that sensor’s R', 'Resample both to 25 Hz by averaging the rates', 'Drop the camera', 'Ignore timestamps'], 'The filter can take updates whenever data arrive.'),
      info('Shape of the answer', 'Start with one sentence of intuition, then the two steps, then the gain, then one failure mode. Offer to write the equations; do not recite them unasked.'),
      order('Order a strong answer to "How would you verify a tracker in the field?"', ['Record sensor data and a reference measurement on test drives', 'Log the innovations and their predicted covariance', 'Check the mean is near zero and about 95 % lie within two standard deviations', 'Compare tracking error with the reference by scenario', 'Retune Q and R and repeat'], 'Measure, check consistency, compare, tune.'),
      tf('For a linear system with Gaussian noise the Kalman filter is the minimum mean-square-error estimator.', true, 'That is the classical optimality result.'))
  ],

  'fusion-arch': [
    L('Why fuse?',
      info('The whole is better', 'A camera says "that is a pedestrian" but is vague about distance. A radar says "something is 23.4 m away, approaching at 1.2 m/s" but not what it is.\n\n**Sensor fusion** combines them: a pedestrian, 23.4 m away, approaching at 1.2 m/s.'),
      match('Match the benefit', [['Complementarity', 'Each sensor supplies what another lacks'], ['Redundancy', 'A second sensor covers a failure of the first'], ['Accuracy', 'Combined estimates are more certain'], ['Coverage', 'Together they see all around the vehicle']]),
      mc('Camera gives class, radar gives range and speed. This is…', ['Complementary fusion', 'Redundant fusion only', 'No fusion', 'Calibration'], 'Different information about the same object.'),
      mc('Two radars watch the same area and one fails. The system still works thanks to…', ['Redundancy', 'Complementarity', 'Resolution', 'Luck'], 'Important for safety.'),
      info('Three things must be right first', '1. **Space:** every measurement in one coordinate frame (**extrinsic calibration**).\n2. **Time:** every measurement referred to the same instant (**synchronisation**).\n3. **Uncertainty:** how much to trust each one.'),
      type('A car moves at 30 m/s. Two sensors’ timestamps differ by 0.05 s. How many metres of position error does that cause?', ['1.5'], '30 × 0.05.'),
      mc('A camera’s yaw calibration is off by 1 degree. At 100 m the sideways error is about…', ['1.7 m', '1.7 cm', '17 m', 'Zero'], '100 × tan(1°).'),
      tf('Fusion can compensate for badly wrong calibration without any cost.', false, 'Misaligned data produces ghost objects or missed matches.')),

    L('Where to fuse',
      info('Early, mid or late', '**Early (low-level):** combine raw data before detection. Keeps the most information; needs tight calibration and heavy compute.\n\n**Mid-level:** merge learned feature maps, often in a bird’s-eye-view grid.\n\n**Late (object-level):** each sensor detects objects; a tracker fuses the lists. Modular and robust.'),
      match('Match the level', [['Early fusion', 'Raw pixels, points or radar cubes'], ['Mid-level fusion', 'Learned feature maps'], ['Late fusion', 'Object lists from each sensor'], ['Tracking', 'Combining detections over time']]),
      mc('Which level keeps working most easily when one sensor fails?', ['Late fusion', 'Early fusion', 'Neither', 'Both equally'], 'Each sensor’s pipeline is independent.'),
      mc('Which level preserves the most information for the network to exploit?', ['Early fusion', 'Late fusion', 'Tracking only', 'None'], 'Nothing has been thrown away yet.'),
      mc('Radar and camera come from two different suppliers who each deliver object lists. Which fusion fits?', ['Late (object-level) fusion', 'Early fusion', 'No fusion is possible', 'Pixel-level fusion'], 'Supplier interfaces often decide the architecture.'),
      mc('Bird’s-eye-view (BEV) fusion networks…', ['Bring features from all sensors into one top-down grid', 'Work only with ultrasonics', 'Need no calibration', 'Use no neural network'], 'A common mid-level design.'),
      tf('Early fusion is more sensitive to calibration and timing errors than late fusion.', true, 'Raw data must align precisely.'),
      mc('Main drawback of late fusion?', ['Each sensor has already discarded information before fusion', 'It cannot run in real time', 'It needs raw data', 'It is impossible to validate'], 'A weak detection that two sensors could have confirmed together may be lost.')),

    L('Association and tracking',
      info('Which detection belongs to which object?', 'Each cycle brings a fresh list of detections. The tracker must decide which detection updates which existing track. This is **data association**.\n\nSimple: nearest neighbour. Better: the **Hungarian algorithm** for the best overall matching.'),
      order('Order one tracking cycle', ['Predict every track to the measurement time', 'Gate: discard unlikely pairings', 'Associate detections with tracks', 'Update matched tracks', 'Create new tracks and delete stale ones'], 'Predict, gate, associate, update, manage.'),
      mc('A detection matches no existing track. What happens?', ['A new tentative track starts', 'It is always discarded', 'All tracks are deleted', 'The system stops'], 'It is confirmed only after several consistent detections.'),
      mc('Why confirm a track only after several hits?', ['To filter out clutter and false detections', 'To save memory', 'To slow the system', 'Because sensors are perfect'], 'One-off blips should not become objects.'),
      mc('Greedy nearest-neighbour matching can fail in dense traffic because…', ['An early match can take the detection another track needed', 'It is too slow', 'It uses too much RAM', 'It needs lidar'], 'The Hungarian algorithm optimises the total cost.'),
      mc('A better distance than plain Euclidean for association?', ['Mahalanobis distance, which accounts for uncertainty', 'Manhattan distance on colour', 'Hamming distance', 'File size'], 'A 2 m gap matters less when the uncertainty is large.'),
      fillc('if dist > gate:\n    ___   # no further pair is close enough', ['break', 'continue', 'pass', 'return True'], 'Pairs are sorted by distance, so the rest are farther still.'),
      mc('To align a 20 Hz radar with a 30 Hz camera you…', ['Predict or interpolate to a common timestamp', 'Drop the camera', 'Average the two frame rates', 'Ignore time'], 'Compare measurements only at the same instant.')),

    L('Disagreement, safety and interview level',
      info('When sensors disagree', 'First rule out system errors: calibration and timing.\n\nThen weight each sensor by its uncertainty **per quantity**: radar for range and speed, camera for class and lateral position.\n\nKeep an **existence probability** per object: raise it when sensors agree, lower it when they do not.'),
      mc('The camera sees a car that the radar does not. First question to ask?', ['Is the object inside the radar’s field of view and range?', 'Which sensor is more expensive?', 'Is it Tuesday?', 'Should we delete the camera?'], 'A sensor cannot confirm what it cannot see.'),
      mc('Radar reports a strong stationary object on an empty motorway; the camera sees a bridge overhead. Sensible handling?', ['Use the camera and elevation cues to classify it as overhead, not an obstacle', 'Emergency brake immediately', 'Ignore the radar for ever', 'Switch off both'], 'A classic false-positive case; fusion resolves it.'),
      match('Match the safety term', [['ASIL', 'Required safety integrity level'], ['SOTIF', 'Safety despite performance limits'], ['Graceful degradation', 'Reduce function when a sensor is impaired'], ['Plausibility check', 'Reject physically impossible values']]),
      mc('The camera is blinded by low sun. A well-designed system…', ['Detects the degradation and relies more on radar, perhaps limiting the feature', 'Continues unchanged', 'Shuts down the car', 'Trusts the camera more'], 'Sensor health feeds into fusion weights.'),
      order('Order a strong answer to "Camera and radar disagree. What do you do?"', ['Check calibration and time alignment', 'Check field of view and sensor health', 'Weight each sensor by its uncertainty for each quantity', 'Update the object’s existence probability', 'Define a conservative reaction if confidence stays low'], 'System checks first, then statistics, then safety.'),
      mc('Why is radar-camera fusion attractive commercially?', ['Both sensors are cheap and complementary', 'It needs no software', 'It replaces brakes', 'Lidar is forbidden'], 'It covers class, range and speed at low cost.'),
      mc('How do you validate a fusion system?', ['Recorded drives with reference data, simulation, and tests across weather and scenarios', 'One sunny test drive', 'Unit tests only', 'It cannot be validated'], 'Coverage of conditions is the hard part.'),
      tf('Two sensors that agree are stronger evidence than one, because their errors are largely independent.', true, 'That is the statistical heart of fusion.')),

    L('Deeper: track life, frames and distance',
      info('Track life cycle', 'A track is not just "present" or "absent". It moves through states:\n\n- **Tentative:** new, not yet trusted.\n- **Confirmed:** enough hits, reported to the planner.\n- **Coasting:** no recent detection, predicted only.\n- **Deleted:** too many misses.\n\nA common rule is **M of N**: confirm after M hits in the last N cycles.'),
      match('Match the track state', [['Tentative', 'New and not yet confirmed by enough hits'], ['Confirmed', 'Reported to the planner'], ['Coasting', 'Predicted without a recent detection'], ['Deleted', 'Removed after too many misses']]),
      mc('With a 3-of-5 rule, a new track has hits in cycles 1, 2 and 4 and a miss in cycle 3. When is it confirmed?', ['At cycle 4, its third hit within five cycles', 'At cycle 2', 'Never', 'At cycle 5 only'], 'Three hits have been seen by cycle 4.'),
      tf('A coasting track should be reported as if it were freshly measured, with the same confidence.', false, 'Its uncertainty grows, so its confidence must fall.'),
      info('Ego motion changes the frame', 'The vehicle frame moves with the car. A **static** object appears to move toward you at your own speed. Trackers often work in an odometry or world frame, so static objects stay still and the estimate is smoother. That needs the car’s own motion from wheel speed and the inertial unit.'),
      type('A static sign is 20 m ahead. The car moves at 15 m/s. After 0.2 s, how far ahead is the sign in the vehicle frame, in metres?', ['17'], '20 - 15 × 0.2.'),
      type('A bird’s-eye-view grid covers 100 m × 100 m with 0.5 m cells. How many cells does it have?', ['40000', '40,000'], '200 × 200.'),
      type('A detection lies 2 m from the predicted position. The innovation standard deviation is 0.5 m. How many standard deviations away is it?', ['4'], '2 / 0.5.'),
      mc('A gate is set at 3 standard deviations. For that detection the tracker…', ['Rejects it as too far from the prediction', 'Accepts it', 'Doubles the gate automatically', 'Deletes the track'], '4 is outside 3.'),
      mc('Two per-sensor tracks that share the same earlier information are fused as if independent. The fused uncertainty is…', ['Too small, so the result is overconfident', 'Too large', 'Exactly correct', 'Undefined'], 'Correlated errors count twice.')),

    L('Common mistakes and debugging',
      info('Where fusion systems go wrong', 'Most fusion failures in the field are **plumbing**: wrong time, wrong frame, double-counted detections, ID swaps and badly set gates. Check those before changing the maths.'),
      mc('This association code matches a detection to two tracks at once. What is missing?', ['A record of detections and tracks already used', 'A larger gate', 'A sort by time', 'A lower frame rate'], 'Once a detection is taken it must not be reused.', 'for d, t, det in sorted(pairs):\n    if d > gate:\n        break\n    matches.append((t, det))'),
      mc('Sensor data are stamped with `time.time()` when the callback runs. What is the bug?', ['The stamp is the arrival time, not the measurement time', 'The time is in seconds', 'It is too precise', 'It uses an integer'], 'Use the sensor’s own timestamp and the known delay.', 'def on_radar(msg):\n    msg.stamp = time.time()'),
      type('A camera’s yaw is misaligned by 2°. About how many metres sideways is the error for an object 50 m away? (50 × tan 2°, to one decimal place)', ['1.7', '1.75', '1.745'], 'tan 2° is about 0.0349.'),
      mc('Two cars cross paths and their track IDs swap. The most robust fix is to…', ['Add velocity and appearance to the association cost', 'Remove the gate', 'Lower the frame rate', 'Delete all tracks'], 'Position alone is ambiguous at the crossing.'),
      mc('Two radars overlap and each reports the same car. The tracker shows two objects. The fix is to…', ['Transform both to one frame and associate their detections before tracking', 'Delete one radar', 'Raise the radar power', 'Add a second tracker'], 'Duplicates come from association, not from the sensors.'),
      tf('Making the gate as large as possible always improves association.', false, 'Large gates admit wrong matches and clutter.'),
      info('Debug from raw to fused', 'Compare stages: raw detections per sensor in the vehicle frame, then associated pairs, then the fused track, each against a reference. The first stage where the error appears shows where the bug lives.'),
      match('Match the symptom to the likely cause', [['Objects flicker in and out', 'Missing confirmation rule or hysteresis'], ['One object appears twice', 'Missed association between overlapping sensors'], ['Track IDs swap at crossings', 'Cost uses position only'], ['Fused objects trail behind a fast car', 'Wrong or late timestamps']]),
      order('Order the steps to debug a ghost object in fused output', ['Find which sensor produced it in the raw data', 'Check whether it is multipath or clutter', 'Check association and gating around it', 'Check existence-probability handling', 'Add a regression test from the recording'], 'From source to rule to test.')),

    L('Case study: radar and camera for adaptive cruise control',
      info('The scenario', 'A car has a front radar (20 Hz, range error 0.3 m, from supplier A) and a front camera (30 Hz, range error 3 m, class and lane, from supplier B). Each supplier delivers an **object list**. You must decide how to fuse them for adaptive cruise control.'),
      mc('Each supplier delivers only object lists, not raw data. Which architecture fits?', ['Late (object-level) fusion in a tracker', 'Early fusion of raw data', 'Pixel-level fusion', 'No fusion'], 'You cannot fuse raw data you do not have.'),
      type('The radar sees the lead car at 40.0 m at t = 100.00 s and it is closing at 5 m/s. What is the predicted range at the camera time t = 100.02 s, in metres?', ['39.9'], '40.0 - 5 × 0.02.'),
      mc('A camera detection is 1.8 m from the predicted lead car. Radar and camera have different noise. Which distance should associate them?', ['Mahalanobis distance using each sensor’s uncertainty', 'Plain Euclidean distance only', 'Colour distance', 'File size'], 'The gate should reflect each measurement’s noise.'),
      type('The radar says 39.9 m with variance 0.09. The camera says 42.0 m with variance 9. What is the fused range, in metres, to one decimal place?', ['39.9', '39.92'], 'The radar is 100 times more trusted: the result is 39.92 m.'),
      info('Each sensor does what it is best at', 'The fused object takes **range and speed from the radar** and **class and lateral position from the camera**. The tracker also keeps an existence probability: it rises when both agree.'),
      mc('Which sensor should mainly decide whether the lead car is in your lane?', ['The camera, from lane markings and lateral position', 'The radar alone, from range', 'Neither', 'The ultrasonic'], 'Lateral position and lane geometry are the camera’s strength.'),
      mc('At night the camera misses a dark, unlit car that the radar tracks well. A good design…', ['Keeps the radar track, marks its class as unknown and stays cautious', 'Deletes the radar object', 'Waits for the camera', 'Ignores range'], 'One sensor can still carry the track.'),
      order('Order the fusion pipeline', ['Convert both object lists to the vehicle frame', 'Align them to a common time', 'Gate and associate detections with tracks', 'Update each track with each sensor’s noise', 'Output the target in the lane with class and confidence'], 'Frame, time, association, update, output.'),
      mc('How would you validate the whole function before release?', ['Recorded drives with reference data, simulation, and tests in all weather and light', 'One test on a sunny day', 'Unit tests only', 'Trust the suppliers'], 'Coverage of conditions is the hard part.')),

    L('Interview drill: sensor fusion',
      info('What interviewers look for', 'They test that you can **choose and justify** an architecture, **handle time and calibration**, and **measure** the result. They follow with: "what if one sensor fails?", "how do you evaluate it?", "what did you not consider?".'),
      mc('"Early or late fusion for a new system?" The strongest opening is…', ['It depends on the data available, the compute and the safety case; I would state the trade-off and pick', 'Early fusion is always better', 'Late fusion is always better', 'I would use both without explanation'], 'A reasoned trade-off beats a slogan.'),
      type('Quick-fire: two sensors’ timestamps differ by 50 ms and the car moves at 20 m/s. How many metres of position error is that?', ['1'], '20 × 0.05.'),
      mc('"How would you evaluate a tracker?" A complete answer includes…', ['Detection precision and recall by range and condition, position error and ID switches against a reference', 'Only the frame rate', 'Only the code coverage', 'The number of sensors'], 'Stratify by scenario.'),
      match('Match the interviewer’s question to the key idea', [['What if the radar fails?', 'Graceful degradation with the remaining sensors'], ['Why is calibration critical?', 'Misaligned data produce ghosts and missed matches'], ['Why track over time?', 'To filter noise and estimate speed'], ['Why does safety need redundancy?', 'Different sensors rarely fail together']]),
      mc('The interviewer asks what you would do in your first week with an existing fusion stack. A strong answer…', ['Reproduce results on recorded data, read the calibration and timing setup, and review the known failure cases', 'Rewrite it', 'Change all parameters', 'Wait for instructions'], 'Understand and measure before changing.'),
      info('Shape of the answer', 'State the architecture, the three pre-conditions (space, time, uncertainty), the failure handling and the validation. Keep each to one sentence, then let the interviewer choose where to go deeper.'),
      order('Order a strong answer to "Design the fusion for a front camera and radar"', ['State the functions and the failure cases to cover', 'Choose the architecture and justify it', 'Describe calibration, synchronisation and uncertainty handling', 'Describe association, tracking and existence probability', 'Describe degradation handling and validation'], 'Requirements, choice, preconditions, core, safety.'),
      tf('Saying a design has no weaknesses impresses interviewers.', false, 'Honest limits and how you would test them show maturity.'))
  ]
};
